import os
import unittest

from paths import join_path


class TestPaths(unittest.TestCase):
    def test_join(self):
        self.assertEqual(join_path('data', 'rows.txt'), os.path.join('data', 'rows.txt'))
        self.assertEqual(join_path('a', 'b', 'c'), os.path.join('a', 'b', 'c'))


if __name__ == '__main__':
    unittest.main()
